import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_DIGITS = "0123456789"


def _normalize_email(raw):
    s = raw or ""
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            domain = "gmail.com"
        s = f"{local}@{domain}"
    return s


def _valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")


def _normalize_phone(raw):
    s = (raw or "").lower()
    cuts = [p for p in (s.find("x"), s.find("ext"), s.find("#")) if p != -1]
    if cuts:
        s = s[:min(cuts)]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", s)
    if m:
        s = m.group(1)
    if re.fullmatch(r"[0-9]{4}", s):
        s = "0" + s
    if not re.fullmatch(r"[0-9]{5}", s):
        return ""
    return s


def _normalize_name(raw):
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _normalize_tags(raw):
    tags = set()
    for t in re.split(r"[;,]", raw or ""):
        t = t.strip().lower()
        if t:
            tags.add(t)
    return tags


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized updated value: {raw!r}")


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone.
    recs = []
    for row in rows:
        email = _normalize_email(row.get("email", ""))
        if not _valid_email(email):
            email = ""
        phone = _normalize_phone(row.get("phone", ""))
        if not _valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue
        source = (row.get("source") or "").strip().lower()
        recs.append({
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "tags": _normalize_tags(row.get("tags")),
            "opted_out": (row.get("opted_out") or "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
            "manual": source == "manual",
        })

    # Step 2: union-find over rows that share a valid email, or a valid phone
    # plus the same non-empty last name (case-insensitive).
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_by_email = {}
    first_by_phone = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in first_by_email:
                union(i, first_by_email[r["email"]])
            else:
                first_by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in first_by_phone:
                union(i, first_by_phone[key])
            else:
                first_by_phone[key] = i

    # Step 3: group rows, ordered by each group's earliest input row.
    groups = {}
    order = []
    for i in range(n):
        root = find(i)
        if root not in groups:
            groups[root] = []
            order.append(root)
        groups[root].append(i)

    def pick(members, field):
        # Candidates: rows where the field is non-empty.
        # Preference: manual source, then most recent updated, then earliest row.
        cands = sorted(i for i in members if recs[i][field])
        cands.sort(key=lambda i: recs[i]["updated"], reverse=True)  # stable
        cands.sort(key=lambda i: not recs[i]["manual"])             # stable
        return recs[cands[0]][field] if cands else ""

    # Step 4: build one output record per person.
    result = []
    for root in order:
        members = groups[root]
        tags = set()
        for i in members:
            tags |= recs[i]["tags"]
        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(recs[i]["opted_out"] for i in members) else "N",
            "updated": max(recs[i]["updated"] for i in members).strftime("%Y-%m-%d"),
        })
    return result
```

Notes:

- **Opt-outs:** `opted_out` is "Y" for a whole person if any of their rows opted out. Filter with `opted_out == "N"` before the send, so that someone who opted out on one record isn't emailed through another.
- **ZIP+4:** I accept a 4- or 5-digit prefix before the hyphen, so `2139-4307` becomes `02139`, which matches the Excel leading-zero case in rule 4.
- **Bad `updated` values:** the function raises `ValueError` on a value outside the three formats instead of guessing. That's deliberate, so a malformed export fails loudly rather than sorting rows incorrectly.
